create policy "public site content read" on public.schoolpro_site_content for select to anon,authenticated using(is_published=true);
create policy "public gallery read" on public.schoolpro_site_gallery for select to anon,authenticated using(is_published=true);
create policy "public news read" on public.schoolpro_site_news for select to anon,authenticated using(is_published=true);
create policy "school email read" on public.schoolpro_email_queue for select to authenticated using(exists(select 1 from public.schoolpro_members m where m.school_id=schoolpro_email_queue.school_id and m.user_id=auth.uid()));
create policy "school portal invite access" on public.schoolpro_portal_invites for all to authenticated using(exists(select 1 from public.schoolpro_members m where m.school_id=schoolpro_portal_invites.school_id and m.user_id=auth.uid())) with check(exists(select 1 from public.schoolpro_members m where m.school_id=schoolpro_portal_invites.school_id and m.user_id=auth.uid()));
create policy "admission docs staff" on public.schoolpro_admission_documents for all to authenticated using(exists(select 1 from public.schoolpro_admissions a join public.schoolpro_members m on m.school_id=a.school_id where a.id=schoolpro_admission_documents.application_id and m.user_id=auth.uid())) with check(exists(select 1 from public.schoolpro_admissions a join public.schoolpro_members m on m.school_id=a.school_id where a.id=schoolpro_admission_documents.application_id and m.user_id=auth.uid()));
create policy "admission events staff" on public.schoolpro_admission_events for all to authenticated using(exists(select 1 from public.schoolpro_admissions a join public.schoolpro_members m on m.school_id=a.school_id where a.id=schoolpro_admission_events.application_id and m.user_id=auth.uid())) with check(exists(select 1 from public.schoolpro_admissions a join public.schoolpro_members m on m.school_id=a.school_id where a.id=schoolpro_admission_events.application_id and m.user_id=auth.uid()));
create policy "admission offers staff" on public.schoolpro_admission_offers for all to authenticated using(exists(select 1 from public.schoolpro_admissions a join public.schoolpro_members m on m.school_id=a.school_id where a.id=schoolpro_admission_offers.application_id and m.user_id=auth.uid())) with check(exists(select 1 from public.schoolpro_admissions a join public.schoolpro_members m on m.school_id=a.school_id where a.id=schoolpro_admission_offers.application_id and m.user_id=auth.uid()));
create policy "candidate attempts staff" on public.schoolpro_candidate_cbt_attempts for select to authenticated using(exists(select 1 from public.schoolpro_admissions a join public.schoolpro_members m on m.school_id=a.school_id where a.id=schoolpro_candidate_cbt_attempts.application_id and m.user_id=auth.uid()));
create policy "candidate answers staff" on public.schoolpro_candidate_cbt_answers for select to authenticated using(exists(select 1 from public.schoolpro_candidate_cbt_attempts ca join public.schoolpro_admissions a on a.id=ca.application_id join public.schoolpro_members m on m.school_id=a.school_id where ca.id=schoolpro_candidate_cbt_answers.attempt_id and m.user_id=auth.uid()));
create policy "acceptances staff read" on public.schoolpro_admission_acceptances for select to authenticated using(exists(select 1 from public.schoolpro_admissions a join public.schoolpro_members m on m.school_id=a.school_id where a.id=schoolpro_admission_acceptances.application_id and m.user_id=auth.uid()));